    77→/// Handles a request from the HTTP API for full blocks.
    78→#[allow(clippy::too_many_arguments)]
    79→#[instrument(
    80→    name = SPAN_PUBLISH_BLOCK,
    81→    level = "info",
    82→    skip_all,
    83→    fields(?block_root, ?validation_level, provenance = tracing::field::Empty)
    84→)]
    85→pub async fn publish_block<T: BeaconChainTypes, B: IntoGossipVerifiedBlock<T>>(
    86→    block_root: Option<Hash256>,
    87→    provenanced_block: ProvenancedBlock<T, B>,
    88→    chain: Arc<BeaconChain<T>>,
    89→    network_tx: &UnboundedSender<NetworkMessage<T::EthSpec>>,
    90→    validation_level: BroadcastValidation,
    91→    duplicate_status_code: StatusCode,
    92→) -> Result<Response, Rejection> {
    93→    let seen_timestamp = timestamp_now();
    94→    let block_publishing_delay_for_testing = chain.config.block_publishing_delay;
    95→    let data_column_publishing_delay_for_testing = chain.config.data_column_publishing_delay;
    96→
    97→    let (unverified_block, unverified_blobs, is_locally_built_block) = match provenanced_block {
    98→        ProvenancedBlock::Local(block, blobs, _) => (block, blobs, true),
    99→        ProvenancedBlock::Builder(block, blobs, _) => (block, blobs, false),
   100→    };
   101→    let provenance = if is_locally_built_block {
   102→        "local"
   103→    } else {
   104→        "builder"
   105→    };
   106→    let current_span = Span::current();
   107→    current_span.record("provenance", provenance);
   108→
   109→    let block = unverified_block.inner_block();
   110→
   111→    debug!(slot = %block.slot(), "Signed block received in HTTP API");
   112→
   113→    /* actually publish a block */
   114→    let publish_block_p2p = move |block: Arc<SignedBeaconBlock<T::EthSpec>>,
   115→                                  sender,
   116→                                  seen_timestamp|
   117→          -> Result<(), BlockError> {
   118→        let publish_timestamp = timestamp_now();
   119→        let publish_delay = publish_timestamp
   120→            .checked_sub(seen_timestamp)
   121→            .unwrap_or_else(|| Duration::from_secs(0));
   122→
   123→        metrics::observe_timer_vec(
   124→            &metrics::HTTP_API_BLOCK_GOSSIP_TIMES,
   125→            &[provenance],
   126→            publish_delay,
   127→        );
   128→
   129→        info!(
   130→            slot = %block.slot(),
   131→            publish_delay_ms = publish_delay.as_millis(),
   132→            "Signed block published to network via HTTP API"
   133→        );
   134→
   135→        crate::publish_pubsub_message(&sender, PubsubMessage::BeaconBlock(block.clone())).map_err(
   136→            |_| BlockError::BeaconChainError(Box::new(BeaconChainError::UnableToPublish)),
   137→        )?;
   138→
   139→        Ok(())
   140→    };
   141→
   142→    /* only publish if gossip- and consensus-valid and equivocation-free */
   143→    let slot = block.message().slot();
   144→    let sender_clone = network_tx.clone();
   145→
   146→    let build_sidecar_task_handle = spawn_build_data_sidecar_task(
   147→        chain.clone(),
   148→        block.clone(),
   149→        unverified_blobs,
   150→        current_span.clone(),
   151→    )?;
   152→
   153→    // Gossip verify the block and blobs/data columns separately.
   154→    let gossip_verified_block_result = unverified_block.into_gossip_verified_block(&chain);
   155→    let block_root = block_root.unwrap_or_else(|| {
   156→        gossip_verified_block_result.as_ref().map_or_else(
   157→            |_| block.canonical_root(),
   158→            |verified_block| verified_block.block_root,
   159→        )
   160→    });
   161→
   162→    let should_publish_block = gossip_verified_block_result.is_ok();
   163→    if BroadcastValidation::Gossip == validation_level && should_publish_block {
   164→        if let Some(block_publishing_delay) = block_publishing_delay_for_testing {
   165→            debug!(
   166→                ?block_publishing_delay,
   167→                "Publishing block with artificial delay"
   168→            );
   169→            tokio::time::sleep(block_publishing_delay).await;
   170→        }
   171→        publish_block_p2p(block.clone(), sender_clone.clone(), seen_timestamp)
   172→            .map_err(|_| warp_utils::reject::custom_server_error("unable to publish".into()))?;
   173→    }
   174→
   175→    let publish_fn_completed = Arc::new(AtomicBool::new(false));
   176→    let block_to_publish = block.clone();
   177→    let publish_fn = || {
   178→        if should_publish_block {
   179→            match validation_level {
   180→                BroadcastValidation::Gossip => (),
   181→                BroadcastValidation::Consensus => publish_block_p2p(
   182→                    block_to_publish.clone(),
   183→                    sender_clone.clone(),
   184→                    seen_timestamp,
   185→                )?,
   186→                BroadcastValidation::ConsensusAndEquivocation => {
   187→                    check_slashable(&chain, block_root, &block_to_publish)?;
   188→                    publish_block_p2p(
   189→                        block_to_publish.clone(),
   190→                        sender_clone.clone(),
   191→                        seen_timestamp,
   192→                    )?;
   193→                }
   194→            };
   195→        }
   196→
   197→        publish_fn_completed.store(true, Ordering::SeqCst);
   198→        Ok(())
   199→    };
   200→
   201→    // Wait for blobs/columns to get gossip verified before proceeding further as we need them for import.
   202→    let (gossip_verified_blobs, gossip_verified_columns) = build_sidecar_task_handle.await?;
   203→
   204→    for blob in gossip_verified_blobs.into_iter().flatten() {
   205→        publish_blob_sidecars(network_tx, &blob).map_err(|_| {
   206→            warp_utils::reject::custom_server_error("unable to publish blob sidecars".into())
   207→        })?;
   208→        if let Err(e) = Box::pin(chain.process_gossip_blob(blob)).await {
   209→            let msg = format!("Invalid blob: {e}");
   210→            return if let BroadcastValidation::Gossip = validation_level {
   211→                Err(warp_utils::reject::broadcast_without_import(msg))
   212→            } else {
   213→                error!(reason = &msg, "Invalid blob provided to HTTP API");
   214→                Err(warp_utils::reject::custom_bad_request(msg))
   215→            };
   216→        }
   217→    }
   218→
   219→    if !gossip_verified_columns.is_empty() {
   220→        if let Some(data_column_publishing_delay) = data_column_publishing_delay_for_testing {
   221→            // Subtract block publishing delay if it is also used.
   222→            // Note: if `data_column_publishing_delay` is less than `block_publishing_delay`, it
   223→            // will still be delayed by `block_publishing_delay`. This could be solved with spawning
   224→            // async tasks but the limitation is minor and I believe it's probably not worth
   225→            // affecting the mainnet code path.
   226→            let block_publishing_delay = block_publishing_delay_for_testing.unwrap_or_default();
   227→            let delay = data_column_publishing_delay.saturating_sub(block_publishing_delay);
   228→            if !delay.is_zero() {
   229→                debug!(
   230→                    ?data_column_publishing_delay,
   231→                    "Publishing data columns with artificial delay"
   232→                );
   233→                tokio::time::sleep(delay).await;
   234→            }
   235→        }
   236→        publish_column_sidecars(network_tx, &gossip_verified_columns, &chain).map_err(|_| {
   237→            warp_utils::reject::custom_server_error("unable to publish data column sidecars".into())
   238→        })?;
   239→        let epoch = block.slot().epoch(T::EthSpec::slots_per_epoch());
   240→        let sampling_columns_indices = chain.sampling_columns_for_epoch(epoch);
   241→        let sampling_columns = gossip_verified_columns
   242→            .into_iter()
   243→            .filter(|data_column| sampling_columns_indices.contains(&data_column.index()))
   244→            .collect::<Vec<_>>();
   245→
   246→        if !sampling_columns.is_empty() {
   247→            // Importing the columns could trigger block import and network publication in the case
   248→            // where the block was already seen on gossip.
   249→            if let Err(e) =
   250→                Box::pin(chain.process_gossip_data_columns(sampling_columns, publish_fn)).await
   251→            {
   252→                let msg = format!("Invalid data column: {e}");
   253→                return if let BroadcastValidation::Gossip = validation_level {
   254→                    Err(warp_utils::reject::broadcast_without_import(msg))
   255→                } else {
   256→                    error!(
   257→                        reason = &msg,
   258→                        "Invalid data column during block publication"
   259→                    );
   260→                    Err(warp_utils::reject::custom_bad_request(msg))
   261→                };
   262→            }
   263→        }
   264→    }
   265→
   266→    match gossip_verified_block_result {
   267→        Ok(gossip_verified_block) => {
   268→            let import_result = Box::pin(chain.process_block(
   269→                block_root,
   270→                gossip_verified_block,
   271→                NotifyExecutionLayer::Yes,
   272→                BlockImportSource::HttpApi,
   273→                publish_fn,
   274→            ))
   275→            .await;
   276→            post_block_import_logging_and_response(
   277→                import_result,
   278→                validation_level,
   279→                block,
   280→                is_locally_built_block,
   281→                seen_timestamp,
   282→                &chain,
   283→            )
   284→            .await
   285→        }
   286→        Err(BlockError::DuplicateFullyImported(root)) => {
   287→            if publish_fn_completed.load(Ordering::SeqCst) {
   288→                post_block_import_logging_and_response(
   289→                    Ok(AvailabilityProcessingStatus::Imported(root)),
   290→                    validation_level,
   291→                    block,
   292→                    is_locally_built_block,
   293→                    seen_timestamp,
   294→                    &chain,
   295→                )
   296→                .await
   297→            } else {
   298→                // None of the components provided in this HTTP request were new, so this was an
   299→                // entirely redundant duplicate request. Return a status code indicating this,
   300→                // which can be overridden based on config.
   301→                Ok(warp::reply::with_status(
   302→                    warp::reply::json(&ErrorMessage {
   303→                        code: duplicate_status_code.as_u16(),
   304→                        message: "duplicate block".to_string(),
   305→                        stacktraces: vec![],
   306→                    }),
   307→                    duplicate_status_code,
   308→                )
   309→                .into_response())
   310→            }
   311→        }
   312→        Err(BlockError::DuplicateImportStatusUnknown(root)) => {
   313→            debug!(
   314→                block_root = ?root,
   315→                slot = %block.slot(),
   316→                "Block previously seen"
   317→            );
   318→            let import_result = Box::pin(chain.process_block(
   319→                block_root,
   320→                RpcBlock::new_without_blobs(Some(block_root), block.clone()),
   321→                NotifyExecutionLayer::Yes,
   322→                BlockImportSource::HttpApi,
   323→                publish_fn,
   324→            ))
   325→            .await;
   326→            post_block_import_logging_and_response(
   327→                import_result,
   328→                validation_level,
   329→                block,
   330→                is_locally_built_block,
   331→                seen_timestamp,
   332→                &chain,
   333→            )
   334→            .await
   335→        }
   336→        Err(e) => {
   337→            warn!(
   338→                %slot,
   339→                error = %e,
   340→                "Not publishing block - not gossip verified"
   341→            );
   342→            Err(warp_utils::reject::custom_bad_request(e.to_string()))
   343→        }
   344→    }
   345→}
   346→
   347→type BuildDataSidecarTaskResult<T> = Result<
   348→    (
   349→        Vec<Option<GossipVerifiedBlob<T>>>,
   350→        Vec<GossipVerifiedDataColumn<T>>,
   351→    ),
   352→    Rejection,
   353→>;
   354→
   355→/// Convert blobs to either:
   356→///
   357→/// 1. Blob sidecars if prior to peer DAS, or
   358→/// 2. Data column sidecars if post peer DAS.
   359→fn spawn_build_data_sidecar_task<T: BeaconChainTypes>(
   360→    chain: Arc<BeaconChain<T>>,
   361→    block: Arc<SignedBeaconBlock<T::EthSpec, FullPayload<T::EthSpec>>>,
   362→    proofs_and_blobs: UnverifiedBlobs<T>,
   363→    current_span: Span,
   364→) -> Result<impl Future<Output = BuildDataSidecarTaskResult<T>>, Rejection> {
   365→    chain
   366→        .clone()
   367→        .task_executor
   368→        .spawn_blocking_handle(
   369→            move || {
   370→                let Some((kzg_proofs, blobs)) = proofs_and_blobs else {
   371→                    return Ok((vec![], vec![]));
   372→                };
   373→                let _guard = debug_span!(parent: current_span, "build_data_sidecars").entered();
   374→
   375→                let peer_das_enabled = chain.spec.is_peer_das_enabled_for_epoch(block.epoch());
   376→                if !peer_das_enabled {
   377→                    // Pre-PeerDAS: construct blob sidecars for the network.
   378→                    let gossip_verified_blobs =
   379→                        build_gossip_verified_blobs(&chain, &block, blobs, kzg_proofs)?;
   380→                    Ok((gossip_verified_blobs, vec![]))
   381→                } else {
   382→                    // Post PeerDAS: construct data columns.
   383→                    let gossip_verified_data_columns =
   384→                        build_data_columns(&chain, &block, blobs, kzg_proofs)?;
   385→                    Ok((vec![], gossip_verified_data_columns))
   386→                }
   387→            },
   388→            "build_data_sidecars",
   389→        )
   390→        .ok_or(warp_utils::reject::custom_server_error(
   391→            "runtime shutdown".to_string(),
   392→        ))
   393→        .map(|r| {
   394→            r.map_err(|_| warp_utils::reject::custom_server_error("join error".to_string()))
   395→                .and_then(|output| async move { output })
   396→        })
   397→}
   398→
   399→/// Build data columns as wrapped `GossipVerifiedDataColumn`s.
   400→/// There is no need to actually perform gossip verification on columns that a block producer
   401→/// is publishing. In the locally constructed case, cell proof verification happens in the EL.
   402→/// In the externally constructed case, there wont be any columns here.
   403→fn build_data_columns<T: BeaconChainTypes>(
   404→    chain: &BeaconChain<T>,
   405→    block: &SignedBeaconBlock<T::EthSpec, FullPayload<T::EthSpec>>,
   406→    blobs: BlobsList<T::EthSpec>,
   407→    kzg_cell_proofs: KzgProofs<T::EthSpec>,
   408→) -> Result<Vec<GossipVerifiedDataColumn<T>>, Rejection> {
   409→    let slot = block.slot();
   410→    let data_column_sidecars =
   411→        build_blob_data_column_sidecars(chain, block, blobs, kzg_cell_proofs).map_err(|e| {
   412→            error!(
   413→                error = ?e,
   414→                %slot,
   415→                "Invalid data column - not publishing block"
   416→            );
   417→            warp_utils::reject::custom_bad_request(format!("{e:?}"))
   418→        })?;
   419→
   420→    let gossip_verified_data_columns = data_column_sidecars
   421→        .into_iter()
   422→        .filter_map(|data_column_sidecar| {
   423→            GossipVerifiedDataColumn::new_for_block_publishing(data_column_sidecar, chain).ok()
   424→        })
   425→        .collect::<Vec<_>>();
   426→
   427→    Ok(gossip_verified_data_columns)
   428→}
   429→
   430→fn build_gossip_verified_blobs<T: BeaconChainTypes>(
   431→    chain: &BeaconChain<T>,
   432→    block: &SignedBeaconBlock<T::EthSpec, FullPayload<T::EthSpec>>,
   433→    blobs: BlobsList<T::EthSpec>,
   434→    kzg_proofs: KzgProofs<T::EthSpec>,
   435→) -> Result<Vec<Option<GossipVerifiedBlob<T>>>, Rejection> {
   436→    let slot = block.slot();
   437→    let gossip_verified_blobs = kzg_proofs
   438→        .into_iter()
   439→        .zip(blobs)
   440→        .enumerate()
   441→        .map(|(i, (proof, unverified_blob))| {
   442→            let timer = metrics::start_timer(
   443→                &beacon_chain::metrics::BLOB_SIDECAR_INCLUSION_PROOF_COMPUTATION,
   444→            );
   445→            let blob_sidecar = BlobSidecar::new(i, unverified_blob, block, proof)
   446→                .map(Arc::new)
   447→                .map_err(|e| {
   448→                    error!(
   449→                        error = ?e,
   450→                        blob_index = i,
   451→                        %slot,
   452→                        "Invalid blob - not publishing block"
   453→                    );
   454→                    warp_utils::reject::custom_bad_request(format!("{e:?}"))
   455→                })?;
   456→            drop(timer);
   457→
   458→            let gossip_verified_blob =
   459→                GossipVerifiedBlob::new(blob_sidecar.clone(), blob_sidecar.index, chain);
   460→
   461→            match gossip_verified_blob {
   462→                Ok(blob) => Ok(Some(blob)),
   463→                Err(GossipBlobError::RepeatBlob { proposer, .. }) => {
   464→                    // Log the error but do not abort publication, we may need to publish the block
   465→                    // or some of the other blobs if the block & blobs are only partially published
   466→                    // by the other publisher.
   467→                    debug!(
   468→                        blob_index = blob_sidecar.index,
   469→                        %slot,
   470→                        proposer,
   471→                        "Blob for publication already known"
   472→                    );
   473→                    Ok(None)
   474→                }
   475→                Err(e) => {
   476→                    error!(
   477→                        blob_index = blob_sidecar.index,
   478→                        %slot,
   479→                        error = ?e,
   480→                        "Blob for publication is gossip-invalid"
   481→                    );
   482→                    Err(warp_utils::reject::custom_bad_request(e.to_string()))
   483→                }
   484→            }
   485→        })
   486→        .collect::<Result<Vec<_>, Rejection>>()?;
   487→
   488→    Ok(gossip_verified_blobs)
   489→}
   490→
   491→fn publish_blob_sidecars<T: BeaconChainTypes>(
   492→    sender_clone: &UnboundedSender<NetworkMessage<T::EthSpec>>,
   493→    blob: &GossipVerifiedBlob<T>,
   494→) -> Result<(), BlockError> {
   495→    let pubsub_message = PubsubMessage::BlobSidecar(Box::new((blob.index(), blob.clone_blob())));
   496→    crate::publish_pubsub_message(sender_clone, pubsub_message)
   497→        .map_err(|_| BlockError::BeaconChainError(Box::new(BeaconChainError::UnableToPublish)))
   498→}
   499→
   500→fn publish_column_sidecars<T: BeaconChainTypes>(
   501→    sender_clone: &UnboundedSender<NetworkMessage<T::EthSpec>>,
   502→    data_column_sidecars: &[GossipVerifiedDataColumn<T>],
   503→    chain: &BeaconChain<T>,
   504→) -> Result<(), BlockError> {
   505→    let malicious_withhold_count = chain.config.malicious_withhold_count;
   506→    let mut data_column_sidecars = data_column_sidecars
   507→        .iter()
   508→        .map(|d| d.clone_data_column())
   509→        .collect::<Vec<_>>();
   510→    if malicious_withhold_count > 0 {
   511→        let columns_to_keep = data_column_sidecars
   512→            .len()
   513→            .saturating_sub(malicious_withhold_count);
   514→        // Randomize columns before dropping the last malicious_withhold_count items
   515→        data_column_sidecars.shuffle(&mut **chain.rng.lock());
   516→        let dropped_indices = data_column_sidecars
   517→            .drain(columns_to_keep..)
   518→            .map(|d| d.index)
   519→            .collect::<Vec<_>>();
   520→        debug!(indices = ?dropped_indices, "Dropping data columns from publishing");
   521→    }
   522→    let pubsub_messages = data_column_sidecars
   523→        .into_iter()
   524→        .map(|data_col| {
   525→            let subnet = DataColumnSubnetId::from_column_index(data_col.index, &chain.spec);
   526→            PubsubMessage::DataColumnSidecar(Box::new((subnet, data_col)))
   527→        })
   528→        .collect::<Vec<_>>();
   529→    crate::publish_pubsub_messages(sender_clone, pubsub_messages)
   530→        .map_err(|_| BlockError::BeaconChainError(Box::new(BeaconChainError::UnableToPublish)))
   531→}
   532→
   533→async fn post_block_import_logging_and_response<T: BeaconChainTypes>(
   534→    result: Result<AvailabilityProcessingStatus, BlockError>,
   535→    validation_level: BroadcastValidation,
   536→    block: Arc<SignedBeaconBlock<T::EthSpec>>,
   537→    is_locally_built_block: bool,
   538→    seen_timestamp: Duration,
   539→    chain: &Arc<BeaconChain<T>>,
   540→) -> Result<Response, Rejection> {
   541→    match result {
   542→        // The `DuplicateFullyImported` case here captures the case where the block finishes
   543→        // being imported after gossip verification. It could be that it finished imported as a
   544→        // result of the block being imported from gossip, OR it could be that it finished importing
   545→        // after processing of a gossip blob. In the latter case we MUST run fork choice to
   546→        // re-compute the head.
   547→        Ok(AvailabilityProcessingStatus::Imported(root))
   548→        | Err(BlockError::DuplicateFullyImported(root)) => {
   549→            let delay = get_block_delay_ms(seen_timestamp, block.message(), &chain.slot_clock);
   550→            info!(
   551→                block_delay = ?delay,
   552→                root = %root,
   553→                proposer_index = block.message().proposer_index(),
   554→                slot = %block.slot(),
   555→                "Valid block from HTTP API"
   556→            );
   557→
   558→            // Notify the validator monitor.
   559→            chain.validator_monitor.read().register_api_block(
   560→                seen_timestamp,
   561→                block.message(),
   562→                root,
   563→                &chain.slot_clock,
   564→            );
   565→
   566→            // Update the head since it's likely this block will become the new
   567→            // head.
   568→            chain.recompute_head_at_current_slot().await;
   569→
   570→            // Only perform late-block logging here if the block is local. For
   571→            // blocks built with builders we consider the broadcast time to be
   572→            // when the blinded block is published to the builder.
   573→            if is_locally_built_block {
   574→                late_block_logging(chain, seen_timestamp, block.message(), root, "local")
   575→            }
   576→            Ok(warp::reply().into_response())
   577→        }
   578→        Ok(AvailabilityProcessingStatus::MissingComponents(_, block_root)) => {
   579→            let msg = format!("Missing parts of block with root {:?}", block_root);
   580→            if let BroadcastValidation::Gossip = validation_level {
   581→                Err(warp_utils::reject::broadcast_without_import(msg))
   582→            } else {
   583→                error!(reason = &msg, "Invalid block provided to HTTP API");
   584→                Err(warp_utils::reject::custom_bad_request(msg))
   585→            }
   586→        }
   587→        Err(BlockError::BeaconChainError(e))
   588→            if matches!(e.as_ref(), BeaconChainError::UnableToPublish) =>
   589→        {
   590→            Err(warp_utils::reject::custom_server_error(
   591→                "unable to publish to network channel".to_string(),
   592→            ))
   593→        }
   594→        Err(BlockError::Slashable) => Err(warp_utils::reject::custom_bad_request(
   595→            "proposal for this slot and proposer has already been seen".to_string(),
   596→        )),
   597→        Err(e) => {
   598→            if let BroadcastValidation::Gossip = validation_level {
   599→                Err(warp_utils::reject::broadcast_without_import(format!("{e}")))
   600→            } else {
   601→                error!(
   602→                    reason = ?e,
   603→                    "Invalid block provided to HTTP API"
   604→                );
   605→                Err(warp_utils::reject::custom_bad_request(format!(
   606→                    "Invalid block: {e}"
   607→                )))
   608→            }
   609→        }
   610→    }
   611→}
   612→
   613→/// Handles a request from the HTTP API for blinded blocks. This converts blinded blocks into full
   614→/// blocks before publishing.
   615→pub async fn publish_blinded_block<T: BeaconChainTypes>(
   616→    blinded_block: Arc<SignedBlindedBeaconBlock<T::EthSpec>>,
   617→    chain: Arc<BeaconChain<T>>,
   618→    network_tx: &UnboundedSender<NetworkMessage<T::EthSpec>>,
   619→    validation_level: BroadcastValidation,
   620→    duplicate_status_code: StatusCode,
   621→) -> Result<Response, Rejection> {
   622→    let block_root = blinded_block.canonical_root();
   623→    let full_block_opt = reconstruct_block(chain.clone(), block_root, blinded_block).await?;
   624→
   625→    if let Some(full_block) = full_block_opt {
   626→        publish_block::<T, _>(
   627→            Some(block_root),
   628→            full_block,
   629→            chain,
   630→            network_tx,
   631→            validation_level,
   632→            duplicate_status_code,
   633→        )
   634→        .await
   635→    } else {
   636→        // From the fulu fork, builders are responsible for publishing and
   637→        // will no longer return the full payload and blobs.
   638→        Ok(warp::reply().into_response())
   639→    }
   640→}
   641→
   642→/// Deconstruct the given blinded block, and construct a full block. This attempts to use the
   643→/// execution layer's payload cache, and if that misses, attempts a blind block proposal to retrieve
   644→/// the full payload.
   645→///
   646→/// From the Fulu fork, external builders no longer return the full payload and blobs, and this
   647→/// function will always return `Ok(None)` on successful submission of blinded block.
   648→pub async fn reconstruct_block<T: BeaconChainTypes>(
   649→    chain: Arc<BeaconChain<T>>,
   650→    block_root: Hash256,
   651→    block: Arc<SignedBlindedBeaconBlock<T::EthSpec>>,
   652→) -> Result<Option<ProvenancedBlock<T, Arc<SignedBeaconBlock<T::EthSpec>>>>, Rejection> {
   653→    let full_payload_opt = if let Ok(payload_header) = block.message().body().execution_payload() {
   654→        let el = chain.execution_layer.as_ref().ok_or_else(|| {
   655→            warp_utils::reject::custom_server_error("Missing execution layer".to_string())
   656→        })?;
   657→
   658→        // If the execution block hash is zero, use an empty payload.
   659→        let full_payload_contents = if payload_header.block_hash() == ExecutionBlockHash::zero() {
   660→            let fork_name = chain
   661→                .spec
   662→                .fork_name_at_epoch(block.slot().epoch(T::EthSpec::slots_per_epoch()));
   663→            if fork_name == ForkName::Bellatrix {
   664→                let payload: FullPayload<T::EthSpec> = FullPayloadBellatrix::default().into();
   665→                ProvenancedPayload::Local(FullPayloadContents::Payload(payload.into()))
   666→            } else {
   667→                Err(warp_utils::reject::custom_server_error(
   668→                    "Failed to construct full payload - block hash must be non-zero after Bellatrix.".to_string()
   669→                ))?
   670→            }
   671→        // If we already have an execution payload with this transactions root cached, use it.
   672→        } else if let Some(cached_payload) =
   673→            el.get_payload_by_root(&payload_header.tree_hash_root())
   674→        {
   675→            info!(block_hash = ?cached_payload.block_hash(), "Reconstructing a full block using a local payload");
   676→            ProvenancedPayload::Local(cached_payload)
   677→        // Otherwise, this means we are attempting a blind block proposal.
   678→        } else {
   679→            // Perform the logging for late blocks when we publish to the
   680→            // builder, rather than when we publish to the network. This helps
   681→            // prevent false positive logs when the builder publishes to the P2P
   682→            // network significantly earlier than when they return the block to
   683→            // us.
   684→            late_block_logging(
   685→                &chain,
   686→                timestamp_now(),
   687→                block.message(),
   688→                block_root,
   689→                "builder",
   690→            );
   691→
   692→            match el
   693→                .propose_blinded_beacon_block(block_root, &block, &chain.spec)
   694→                .await
   695→                .map_err(|e| {
   696→                    warp_utils::reject::custom_server_error(format!(
   697→                        "Blind block proposal failed: {:?}",
   698→                        e
   699→                    ))
   700→                })? {
   701→                SubmitBlindedBlockResponse::V1(full_payload) => {
   702→                    info!(block_root = ?block_root, "Successfully published a block to the builder network");
   703→                    ProvenancedPayload::Builder(*full_payload)
   704→                }
   705→                SubmitBlindedBlockResponse::V2 => {
   706→                    info!(block_root = ?block_root, "Successfully published a block to the builder network");
   707→                    return Ok(None);
   708→                }
   709→            }
   710→        };
   711→
   712→        Some(full_payload_contents)
   713→    } else {
   714→        None
   715→    };
   716→
   717→    // Perf: cloning the block here to unblind it is a little sub-optimal. This is considered an
   718→    // acceptable tradeoff to avoid passing blocks around on the stack (unarced), which blows up
   719→    // the size of futures.
   720→    let block = (*block).clone();
   721→    match full_payload_opt {
   722→        // A block without a payload is pre-merge and we consider it locally
   723→        // built.
   724→        None => block
   725→            .try_into_full_block(None)
   726→            .ok_or("Failed to build full block with payload".to_string())
   727→            .map(|full_block| ProvenancedBlock::local(Arc::new(full_block), None)),
   728→        Some(ProvenancedPayload::Local(full_payload_contents)) => {
   729→            into_full_block_and_blobs::<T>(block, full_payload_contents)
   730→                .map(|(block, blobs)| ProvenancedBlock::local(block, blobs))
   731→        }
   732→        Some(ProvenancedPayload::Builder(full_payload_contents)) => {
   733→            into_full_block_and_blobs::<T>(block, full_payload_contents)
   734→                .map(|(block, blobs)| ProvenancedBlock::builder(block, blobs))
   735→        }
   736→    }
   737→    .map(Some)
   738→    .map_err(|e| {
   739→        warp_utils::reject::custom_server_error(format!("Unable to add payload to block: {e:?}"))
   740→    })
   741→}
   742→
   743→/// If the `seen_timestamp` is some time after the start of the slot for
   744→/// `block`, create some logs to indicate that the block was published late.
   745→fn late_block_logging<T: BeaconChainTypes, P: AbstractExecPayload<T::EthSpec>>(
   746→    chain: &BeaconChain<T>,
   747→    seen_timestamp: Duration,
   748→    block: BeaconBlockRef<T::EthSpec, P>,
   749→    root: Hash256,
   750→    provenance: &str,
   751→) {
   752→    let delay = get_block_delay_ms(seen_timestamp, block, &chain.slot_clock);
   753→
   754→    metrics::observe_timer_vec(
   755→        &metrics::HTTP_API_BLOCK_BROADCAST_DELAY_TIMES,
   756→        &[provenance],
   757→        delay,
   758→    );
   759→
   760→    // Perform some logging to inform users if their blocks are being produced
   761→    // late.
   762→    //
   763→    // Check to see the thresholds are non-zero to avoid logging errors with small
   764→    // slot times (e.g., during testing)
   765→    let too_late_threshold = chain.slot_clock.unagg_attestation_production_delay();
   766→    let delayed_threshold = too_late_threshold / 2;
   767→    if delay >= too_late_threshold {
   768→        error!(
   769→            msg = "system may be overloaded, block likely to be orphaned",
   770→            provenance,
   771→            delay_ms = delay.as_millis(),
   772→            slot = %block.slot(),
   773→            ?root,
   774→            "Block was broadcast too late"
   775→        )
   776→    } else if delay >= delayed_threshold {
   777→        error!(
   778→            msg = "system may be overloaded, block may be orphaned",
   779→            provenance,
   780→            delay_ms = delay.as_millis(),
   781→            slot = %block.slot(),
   782→            ?root,
   783→            "Block broadcast was delayed"
   784→        )
   785→    }
   786→}
   787→
   788→/// Check if any of the blobs or the block are slashable. Returns `BlockError::Slashable` if so.
   789→fn check_slashable<T: BeaconChainTypes>(
   790→    chain_clone: &BeaconChain<T>,
   791→    block_root: Hash256,
   792→    block_clone: &SignedBeaconBlock<T::EthSpec, FullPayload<T::EthSpec>>,
   793→) -> Result<(), BlockError> {
   794→    let slashable_cache = chain_clone.observed_slashable.read();
   795→    if slashable_cache
   796→        .is_slashable(
   797→            block_clone.slot(),
   798→            block_clone.message().proposer_index(),
   799→            block_root,
   800→        )
   801→        .map_err(|e| BlockError::BeaconChainError(Box::new(e.into())))?
   802→    {
   803→        warn!(
   804→            slot = %block_clone.slot(),
   805→            "Not publishing equivocating block"
   806→        );
   807→        return Err(BlockError::Slashable);
   808→    }
   809→    Ok(())
   810→}
   811→
   812→/// Converting from a `SignedBlindedBeaconBlock` into a full `SignedBlockContents`.
   813→#[allow(clippy::type_complexity)]
   814→pub fn into_full_block_and_blobs<T: BeaconChainTypes>(
   815→    blinded_block: SignedBlindedBeaconBlock<T::EthSpec>,
   816→    maybe_full_payload_contents: FullPayloadContents<T::EthSpec>,
   817→) -> Result<(Arc<SignedBeaconBlock<T::EthSpec>>, UnverifiedBlobs<T>), String> {
   818→    match maybe_full_payload_contents {
   819→        // This variant implies a pre-deneb block
   820→        FullPayloadContents::Payload(execution_payload) => {
   821→            let signed_block = blinded_block
   822→                .try_into_full_block(Some(execution_payload))
   823→                .ok_or("Failed to build full block with payload".to_string())?;
   824→            Ok((Arc::new(signed_block), None))
   825→        }
   826→        // This variant implies a post-deneb block
   827→        FullPayloadContents::PayloadAndBlobs(payload_and_blobs) => {
   828→            let ExecutionPayloadAndBlobs {
   829→                execution_payload,
   830→                blobs_bundle,
   831→            } = payload_and_blobs;
   832→            let signed_block = blinded_block
   833→                .try_into_full_block(Some(execution_payload))
   834→                .ok_or("Failed to build full block with payload".to_string())?;
   835→
   836→            let BlobsBundle {
   837→                commitments: _,
   838→                proofs,
   839→                blobs,
   840→            } = blobs_bundle;
   841→
   842→            Ok((Arc::new(signed_block), Some((proofs, blobs))))
   843→        }
   844→    }
   845→}
